import os

pages = {
    'src/app/products/[category]/page.tsx': '''import { notFound } from "next/navigation"\\nimport { mockCategories } from "@/lib/mock-data/categories"\\nimport { mockProducts } from "@/lib/mock-data/products"\\nimport { PageHero } from "@/components/ui/PageHero"\\nimport { Card } from "@/components/ui/Card"\\nimport { Button } from "@/components/ui/Button"\\nimport { Breadcrumbs } from "@/components/ui/Breadcrumbs"\\nimport Image from "next/image"\\nimport Link from "next/link"\\n\\nexport default async function CategoryPage({ params }: { params: Promise<{ category: string }> }) {\\n  const { category: categorySlug } = await params;\\n  const category = mockCategories.find(c => c.slug === categorySlug)\\n  \\n  if (!category) {\\n    notFound()\\n  }\\n\\n  const categoryProducts = mockProducts.filter(p => p.category_id === category.id)\\n\\n  return (\\n    <div className="flex flex-col gap-12 pb-24">\\n      <PageHero \\n        title={category.name}\\n        description={category.description}\\n        imageSrc={category.image}\\n      />\\n\\n      <section className="container mx-auto px-4">\\n        <Breadcrumbs items={[\\n          { label: 'Products', href: '/products' },\\n          { label: category.name, href: /products/ }\\n        ]} />\\n      </section>\\n\\n      <section className="container mx-auto px-4">\\n        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">\\n          {categoryProducts.map(product => (\\n            <Card key={product.id} className="overflow-hidden group flex flex-col">\\n              <div className="h-64 relative bg-brand-ivory border-b border-brand-navy/5">\\n                <Image \\n                  src={product.image}\\n                  alt={product.name}\\n                  fill\\n                  className="object-cover transition-transform duration-500 group-hover:scale-105"\\n                />\\n              </div>\\n              <div className="p-6 flex flex-col flex-1">\\n                <h3 className="font-serif text-2xl font-bold text-brand-navy mb-2">{product.name}</h3>\\n                <p className="text-sm text-brand-charcoal/70 mb-6 flex-1">{product.shortDescription}</p>\\n                <div className="flex flex-col gap-2 mt-auto">\\n                  <Link href={/products//} className="w-full">\\n                    <Button variant="outline" className="w-full">View Details</Button>\\n                  </Link>\\n                  <Link href={/enquire?product=} className="w-full">\\n                    <Button variant="primary" className="w-full">Enquire Now</Button>\\n                  </Link>\\n                </div>\\n              </div>\\n            </Card>\\n          ))}\\n        </div>\\n      </section>\\n    </div>\\n  )\\n}\\n''',

    'src/app/products/[category]/[product]/page.tsx': '''import { notFound } from "next/navigation"\\nimport { mockCategories } from "@/lib/mock-data/categories"\\nimport { mockProducts } from "@/lib/mock-data/products"\\nimport { Breadcrumbs } from "@/components/ui/Breadcrumbs"\\nimport { Button } from "@/components/ui/Button"\\nimport Image from "next/image"\\nimport Link from "next/link"\\nimport { CheckCircle2 } from "lucide-react"\\n\\nexport default async function ProductDetailPage({ params }: { params: Promise<{ category: string, product: string }> }) {\\n  const { category: categorySlug, product: productSlug } = await params;\\n  const category = mockCategories.find(c => c.slug === categorySlug)\\n  const product = mockProducts.find(p => p.slug === productSlug)\\n\\n  if (!category || !product || product.category_id !== category.id) {\\n    notFound()\\n  }\\n\\n  const relatedProducts = mockProducts.filter(p => p.category_id === category.id && p.id !== product.id).slice(0, 3)\\n\\n  return (\\n    <div className="flex flex-col gap-16 pb-24 pt-8">\\n      <section className="container mx-auto px-4">\\n        <Breadcrumbs items={[\\n          { label: 'Products', href: '/products' },\\n          { label: category.name, href: /products/ },\\n          { label: product.name, href: /products// }\\n        ]} />\\n      </section>\\n\\n      <section className="container mx-auto px-4">\\n        <div className="grid md:grid-cols-2 gap-12 lg:gap-24">\\n          {/* Product Image Gallery Placeholder */}\\n          <div className="relative h-[400px] md:h-[600px] rounded-2xl overflow-hidden border border-brand-navy/10 bg-brand-ivory shadow-lg">\\n            <Image \\n              src={product.image}\\n              alt={product.name}\\n              fill\\n              className="object-cover"\\n              priority\\n            />\\n          </div>\\n\\n          {/* Product Info */}\\n          <div className="space-y-8">\\n            <div>\\n              <span className="text-brand-gold font-sans font-bold text-sm uppercase tracking-wider mb-2 block">{category.name}</span>\\n              <h1 className="text-4xl md:text-5xl font-serif text-brand-navy mb-4">{product.name}</h1>\\n              <p className="text-xl text-brand-charcoal/70 font-sans">{product.shortDescription}</p>\\n            </div>\\n\\n            <div className="prose prose-brand max-w-none">\\n              <p className="text-brand-charcoal/80 leading-relaxed">{product.fullDescription}</p>\\n            </div>\\n\\n            <div className="space-y-4">\\n              <h3 className="font-serif font-bold text-xl text-brand-navy">Key Highlights</h3>\\n              <ul className="space-y-3">\\n                {product.highlights.map((highlight, idx) => (\\n                  <li key={idx} className="flex items-center gap-3 text-brand-charcoal/80">\\n                    <CheckCircle2 className="w-5 h-5 text-brand-gold shrink-0" />\\n                    <span>{highlight}</span>\\n                  </li>\\n                ))}\\n              </ul>\\n            </div>\\n\\n            <div className="pt-8 border-t border-brand-navy/10 flex flex-col sm:flex-row gap-4">\\n              <Link href={/enquire?product=} className="flex-1">\\n                <Button variant="primary" className="w-full text-lg py-6">Enquire for Bulk Order</Button>\\n              </Link>\\n              <Button variant="outline" className="flex-1 text-lg py-6">Download Specs</Button>\\n            </div>\\n          </div>\\n        </div>\\n      </section>\\n\\n      {/* Specifications & Packaging */}\\n      <section className="container mx-auto px-4">\\n        <div className="bg-brand-navy/5 rounded-2xl p-8 md:p-12">\\n          <div className="grid md:grid-cols-2 gap-12">\\n            <div>\\n              <h3 className="font-serif font-bold text-2xl text-brand-navy mb-6">Specifications</h3>\\n              <div className="border border-brand-navy/10 rounded-lg overflow-hidden bg-white">\\n                {Object.entries(product.specifications).map(([key, value], idx) => (\\n                  <div key={key} className={lex justify-between p-4 }>\\n                    <span className="font-medium text-brand-charcoal/60">{key}</span>\\n                    <span className="text-brand-charcoal font-medium text-right">{value}</span>\\n                  </div>\\n                ))}\\n              </div>\\n            </div>\\n            <div>\\n              <h3 className="font-serif font-bold text-2xl text-brand-navy mb-6">Packaging & Logistics</h3>\\n              <div className="bg-white p-6 rounded-lg border border-brand-navy/10">\\n                <h4 className="font-sans font-bold text-brand-charcoal mb-2">Standard Packaging</h4>\\n                <p className="text-brand-charcoal/80 mb-6">{product.packaging}</p>\\n                \\n                <h4 className="font-sans font-bold text-brand-charcoal mb-2">Custom Packaging</h4>\\n                <p className="text-brand-charcoal/80">Available upon request for bulk orders to meet specific import regulations.</p>\\n              </div>\\n            </div>\\n          </div>\\n        </div>\\n      </section>\\n    </div>\\n  )\\n}\\n''',
}

for path, content in pages.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
